package ui

import (
	"github.com/egoist/mygo/ui"
)

// icon parses a 16×16 stroke icon of the design.
func icon(body string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">` + body + `</svg>`))
}

// fluent parses a glyph of Microsoft's Fluent UI System Icons, 20×20 and
// filled (icons-fluent-LICENSE.txt), for what the platforms have a
// standard symbol for: SF Symbols' house, list.bullet, gearshape and
// sidebar.left, which MyGo cannot ask macOS for.
func fluent(d string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path fill="currentColor" d="` + d + `"/></svg>`))
}

